xinshengCustomCss:
.xt-root {
    /* 纯白背景，暗红强调色 */
    --xt-bg: #ffffff; 
    --xt-text: #333333;
    --xt-border: #8b1a1a; 
    --xt-radius: 0px; 
    --xt-font: 'Songti SC', 'SimSun', 'Times New Roman', serif; 
    padding: 25px 20px;
    border: none;
    box-shadow: 0 4px 15px rgba(0,0,0,0.1);
}

/* ================= 1. 顶部新版头 (图二风格) ================= */

/* 顶部小字与右侧双横线 */
.xt-text-headerTop {
    display: flex !important; align-items: center !important;
    font-size: 14px !important; font-weight: bold !important;
    letter-spacing: 4px !important; color: #333 !important;
    font-style: italic !important; background: none !important;
    padding: 0 !important; margin-bottom: 5px !important;
}
.xt-text-headerTop::after {
    content: "" !important; flex: 1 !important;
    border-top: 1px solid #333 !important; border-bottom: 1px solid #333 !important;
    height: 4px !important; margin-left: 15px !important; box-sizing: border-box !important;
}

/* 粗黑横线 */
.xt-divider {
    border-top: 4px solid #333 !important; margin: 0 0 15px 0 !important;
    height: 0 !important; background: none !important;
}

/* 红底大标题 (单独成块，横跨全宽) */
.xt-text-headerMain {
    background: #8b1a1a !important; color: #fff !important;
    font-size: 28px !important; font-weight: bold !important; letter-spacing: 2px !important;
    padding: 15px 20px !important; margin-bottom: 25px !important;
    display: flex !important; align-items: center !important; justify-content: space-between !important;
    border-left: 6px solid #dcb5b5 !important; 
    border-radius: 0 !important; box-shadow: none !important;
}
.xt-text-headerMain::after {
    content: "”" !important; font-size: 40px !important; font-family: 'Times New Roman', serif !important;
    line-height: 0 !important; margin-top: 15px !important; color: #fff !important;
}

/* ================= 2. 文章排版 ================= */

.xt-text-newsTitle, .xt-text-voiceTitle {
    color: #8b1a1a; font-size: 22px; line-height: 1.4; border-left: 4px solid #8b1a1a;
    padding-left: 12px; margin: 0 0 15px 0; background: none; border-radius: 0; font-weight: bold;
}
.xt-text-newsContent, .xt-text-innerVoice {
    font-size: 15px; line-height: 1.8; color: #333; text-align: justify; text-indent: 2em;
    white-space: pre-wrap; background: none; padding: 0; margin-bottom: 15px;
}
.xt-image { border: 1px solid #eee; padding: 8px; background: #f9f9f9; margin-bottom: 8px; border-radius: 0; }
.xt-image img { width: 100%; aspect-ratio: 16 / 9; object-fit: cover; display: block; }
.xt-text-caption1, .xt-text-caption2 {
    text-align: center; color: #888; font-size: 13px; font-style: italic;
    background: none; padding: 0; margin-bottom: 30px;
}

/* ================= 3. 互动小板块 ================= */

/* 8. 进程版头（大字报排版） */
.xt-text-progressSub {
    text-align: left !important; font-size: 16px !important; font-weight: 900 !important; 
    color: #444 !important; letter-spacing: 1px !important; 
    margin-bottom: 0 !important; 
    background: none !important; padding: 0 0 0 5px !important;
}
.xt-text-progressTitle {
    text-align: left !important; font-size: 52px !important; font-weight: 900 !important; 
    color: #222 !important; letter-spacing: -2px !important; 
    line-height: 1.1 !important; margin-bottom: 15px !important;
    border: none !important; padding: 0 !important; background: none !important;
    font-family: 'SimHei', sans-serif !important; 
}
.xt-text-progressTag1, .xt-text-progressTag2 {
    text-align: left !important; font-size: 14px !important; font-weight: bold !important;
    color: #fff !important; background: #8b1a1a !important; 
    padding: 4px 10px !important; margin-bottom: 6px !important;
    width: fit-content !important; 
    line-height: 1.2 !important; border-radius: 0 !important;
}
.xt-text-progressTag1::before, .xt-text-progressTag2::before {
    content: "# " !important; font-weight: 900 !important; opacity: 0.8 !important; margin-right: 2px !important;
}

/* 9. 刮刮乐悄悄话 */
.xt-content > .xt-card:nth-of-type(1) {
    background: transparent !important; border: 1px solid #8b1a1a !important; border-radius: 0 !important; padding: 15px !important; margin-top: 25px !important; margin-bottom: 25px !important;
}
.xt-content > .xt-card:nth-of-type(1) .xt-card-title {
    color: #8b1a1a !important; text-align: center !important; font-size: 16px !important; font-weight: bold !important; margin-bottom: 10px !important; border-bottom: 1px dashed #8b1a1a !important; padding-bottom: 8px !important;
}
.xt-text-secretWhisper {
    background: none; padding: 0; font-size: 15px; font-weight: bold; text-align: center; filter: blur(6px); transition: filter 0.4s ease; color: #333;
}
.xt-action-1 {
    display: block; text-align: center; border: 1px solid #8b1a1a; padding: 6px; margin-top: 12px; font-size: 12px; color: #8b1a1a; cursor: pointer;
}
.xt-action-1::after { content: "点击刮开涂层"; }
#xt-t1:checked ~ .xt-content .xt-text-secretWhisper { filter: none; }
#xt-t1:checked ~ .xt-content .xt-action-1::after { content: "已阅"; }
#xt-t1:checked ~ .xt-content .xt-action-1 { background: #8b1a1a; color: #fff; }

/* 10. 左右双栏：左快报 | 右广告 */
.xt-content > .xt-row:nth-of-type(1) { 
    align-items: flex-start !important; gap: 0 !important; margin-bottom: 25px !important;
    border-top: 1px solid #8b1a1a !important; border-bottom: 1px solid #8b1a1a !important; 
    border-left: none !important; border-right: none !important;
    border-radius: 0 !important; 
    padding: 15px 0 !important; background: transparent !important;
}
.xt-text-shortNews, .xt-text-adText {
    background: none !important; padding: 0 15px !important; font-size: 14px !important; 
    line-height: 1.6 !important; text-align: justify !important; color: #333 !important;
    border-radius: 0 !important;
}
.xt-text-shortNews { border-right: 1px solid #8b1a1a !important; }
.xt-text-shortNews::before {
    content: "街头快报" !important; display: block !important; text-align: center !important; color: #8b1a1a !important; font-size: 15px !important; font-weight: bold !important; margin-bottom: 10px !important;
}
.xt-text-adText::before {
    content: "赞助广告" !important; display: block !important; text-align: center !important; color: #8b1a1a !important; font-size: 15px !important; font-weight: bold !important; margin-bottom: 10px !important;
}

/* 11. 底部规章制度 (修复长文字遮挡问题) */
.xt-section {
    border: 1px dashed #8b1a1a; background: #fdfaf4; 
    padding: 15px !important; /* 恢复正常内边距 */
    margin-bottom: 5px;
    position: relative !important; 
    min-height: 140px !important; /* 保证高度足够容纳竖排标题 */
}
.xt-section-title {
    color: #ffffff !important; background: #8b1a1a !important; /* 红底白字 */
    font-size: 14px !important; font-weight: bold !important; 
    padding: 12px 6px !important; 
    border-radius: 2px !important;
    position: absolute !important; 
    right: 15px !important; /* 紧贴右侧 */
    top: 15px !important; /* 紧贴顶部 */
    writing-mode: vertical-rl !important; /* 竖向排版 */
    letter-spacing: 2px !important; 
    margin: 0 !important;
    z-index: 2 !important; /* 确保悬浮在最上层 */
}
.xt-section-body { 
    background: none; border: none; padding: 0; text-align: left; 
    margin-right: 55px !important; /* 核心修复：强制内部文字提前换行，给右侧标题让出绝对安全空间 */
}
.xt-list { background: none; border: none; padding: 0; counter-reset: rule-counter; }
.xt-list-item { margin-bottom: 6px; }
.xt-list-check { display: none; }
.xt-list-item::before {
    counter-increment: rule-counter; content: counter(rule-counter) ". ";
    font-weight: bold; color: #8b1a1a; margin-right: 5px;
}
.xt-list-text { font-size: 14px; color: #333; line-height: 1.6; }

/* ================= 12. 杂志风访谈排版 ================= */

.xt-text-interviewTop {
    font-size: 14px; letter-spacing: 0.8em; color: #8b1a1a; font-weight: bold;
    margin-top: 40px; margin-bottom: 20px; background: none; padding: 0; 
}
.xt-content > .xt-row:last-of-type {
    align-items: flex-end !important; border: none !important; padding: 0 !important; 
    margin-bottom: 10px !important; gap: 20px !important; 
}
.xt-content > .xt-row:last-of-type .xt-card {
    background: transparent !important; border: none !important; padding: 0 !important; 
    margin: 0 !important; box-shadow: none !important;
}
.xt-content > .xt-row:last-of-type .xt-card-title { display: none !important; }

.xt-text-charName {
    font-size: 32px; font-family: 'Songti SC', serif; color: #333;
    line-height: 1.2; background: none; padding: 0; margin-bottom: 5px;
}
.xt-text-interviewTitle {
    font-size: 18px; font-family: 'Songti SC', serif; color: #8b1a1a;
    font-weight: bold; background: none; padding: 0; margin-bottom: 15px;
}
.xt-text-interviewQuestion {
    font-size: 13px; color: #666; font-style: italic;
    background: none; padding: 0; line-height: 1.6;
}
.xt-text-interviewContent {
    font-size: 13px; line-height: 1.8; color: #555; text-align: justify;
    background: none; padding: 0; position: relative;
}
.xt-text-interviewContent::before {
    content: "“" !important; float: left !important; font-size: 60px !important;
    font-family: 'Times New Roman', serif !important; font-weight: 900 !important;
    color: #8b1a1a !important; line-height: 0.8 !important;
    margin-right: 8px !important; margin-top: 8px !important; 
}

